1	import * as fs from "node:fs";
2	import * as path from "node:path";
3	import { google, gmail_v1 } from "googleapis";
4	import { authorize } from "./gmail-auth";
5	import { summarize, OLLAMA_MODEL } from "./summarize";
6	import { mergeContact } from "./merge";
7	import { splitName } from "./create-contact";
8	import { parseFrontmatterEmails } from "./frontmatter";
9	
10	// Slice 2 — Incremental per-contact search, READ-ONLY DRY-RUN.
11	//
12	// For each contact file passed as an argument, search Mark's Gmail for the
13	// contact's address(es), derive direction, dedup against entries already in the
14	// file, and PRINT the proposed new "Mark's Email History" entries plus the
15	// last_searched date that *would* be written. Writes nothing.
16	//
17	//   env "$(op environment read <item-id>)" npm run gmail-sync -- friends/blyth-don.md ...
18	//
19	// First run (no last_searched in frontmatter) searches all history, ignoring
20	// last_updated. Once last_searched exists it bounds the query with after:.
21	
22	const ROOT = path.resolve(__dirname, "..");
23	
24	// How far back the FIRST run reaches, per category, so an initial scan of a
25	// decades-deep mailbox doesn't take forever. Incremental runs ignore this — they
26	// are bounded by last_searched instead.
27	const YEARS_BACK: Record<string, number> = {
28	  client: 3,
29	  colleague: 3,
30	  friend: 10,
31	};
32	
33	// Safety cap so a mis-built query can't page forever; we log if we hit it.
34	const MAX_MESSAGES_PER_CONTACT = 2000;
35	
36	// Retry Gmail calls on rate-limit / transient errors with exponential backoff.
37	async function withBackoff<T>(fn: () => Promise<T>, label: string): Promise<T> {
38	  const maxRetries = 6;
39	  let delay = 500;
40	  for (let attempt = 0; ; attempt++) {
41	    try {
42	      return await fn();
43	    } catch (err: unknown) {
44	      const e = err as {
45	        code?: number;
46	        response?: { status?: number };
47	        errors?: Array<{ reason?: string }>;
48	      };
49	      const status = e.code ?? e.response?.status;
50	      const reason = e.errors?.[0]?.reason ?? "";
51	      const retryable =
52	        status === 429 ||
53	        status === 500 ||
54	        status === 503 ||
55	        (status === 403 && /rateLimit|userRateLimit|quota/i.test(reason));
56	      if (!retryable || attempt >= maxRetries) throw err;
57	      const wait = delay + Math.floor(Math.random() * 250);
58	      console.error(
59	        `  ⏳ ${label}: ${status} ${reason} — retry ${attempt + 1}/${maxRetries} in ${wait}ms`
60	      );
61	      await new Promise((r) => setTimeout(r, wait));
62	      delay = Math.min(delay * 2, 16000);
63	    }
64	  }
65	}
66	
67	// ─── Contact file parsing ────────────────────────────────────────────────────
68	
69	interface Contact {
70	  filePath: string;
71	  category: string; // client | friend | colleague
72	  firstName: string | null; // for name-led summaries
73	  needsName: boolean; // true when frontmatter has no first/last name to go on
74	  emails: string[]; // lowercased
75	  lastSearched: string | null; // YYYY-MM-DD or null
76	  existingMessageIds: Set<string>; // Gmail hex ids already recorded
77	  existingLegacyKeys: Set<string>; // date|subject|direction|thread for old entries
78	}
79	
80	// Match on a path *segment* so both relative ("friends/x.md") and absolute
81	// paths work — the earlier "/friends/" substring test missed relative args.
82	function categoryFor(contactPath: string): string {
83	  const segs = contactPath.replace(/\\/g, "/").split("/");
84	  if (segs.includes("friends")) return "friend";
85	  if (segs.includes("colleagues")) return "colleague";
86	  return "client";
87	}
88	
89	function unquote(s: string): string {
90	  return s.trim().replace(/^["']|["']$/g, "").trim();
91	}
92	
93	function parseContact(contactPath: string): Contact {
94	  const abs = path.isAbsolute(contactPath)
95	    ? contactPath
96	    : path.join(ROOT, contactPath);
97	  const raw = fs.readFileSync(abs, "utf-8");
98	
99	  const fmMatch = raw.match(/^---\r?\n([\s\S]*?)\r?\n---/);
100	  if (!fmMatch) throw new Error(`No YAML frontmatter in ${contactPath}`);
101	  const fmLines = fmMatch[1].split(/\r?\n/);
102	
103	  // Addresses: tolerant of email:/emails: and string/list/inline-array shapes.
104	  const emails = parseFrontmatterEmails(fmLines);
105	  let lastSearched: string | null = null;
106	  let firstName: string | null = null;
107	  let lastName: string | null = null;
108	
109	  for (const line of fmLines) {
110	    const fn = line.match(/^first_name:\s*(.+)$/);
111	    if (fn) {
112	      firstName = unquote(fn[1]) || null;
113	      continue;
114	    }
115	    const ln = line.match(/^last_name:\s*(.+)$/);
116	    if (ln) {
117	      lastName = unquote(ln[1]) || null;
118	      continue;
119	    }
120	    const ls = line.match(/^last_searched:\s*(.+)$/);
121	    if (ls) lastSearched = unquote(ls[1]) || null;
122	  }
123	
124	  // Existing entries: collect Gmail message ids and legacy dedup keys from the
125	  // "## Mark's Email History" section only.
126	  const existingMessageIds = new Set<string>();
127	  const existingLegacyKeys = new Set<string>();
128	  const markSection = raw.split(/^##\s+Mark's Email History\s*$/m)[1];
129	  if (markSection) {
130	    // Cut it off at the next H2 (e.g. "## Email History").
131	    const section = markSection.split(/^##\s+/m)[0];
132	    let curDate = "";
133	    let curSubject = "";
134	    let curDirection = "";
135	    let curThread = "";
136	    let curMessage = "";
137	    const flushLegacy = () => {
138	      if (curSubject && !curMessage) {
139	        existingLegacyKeys.add(
140	          `${curDate}|${curSubject}|${curDirection}|${curThread}`
141	        );
142	      }
143	      curSubject = curDirection = curThread = curMessage = "";
144	    };
145	    for (const line of section.split(/\r?\n/)) {
146	      const dateM = line.match(/^###\s+(\d{4}-\d{2}-\d{2})/);
147	      if (dateM) {
148	        flushLegacy();
149	        curDate = dateM[1];
150	        continue;
151	      }
152	      const subjM = line.match(/^-\s+\*\*Subject:\*\*\s*(.+?)\s*$/);
153	      if (subjM) {
154	        flushLegacy();
155	        curSubject = subjM[1];
156	        continue;
157	      }
158	      const dirM = line.match(/^\s*-\s*Direction:\s*(.+?)\s*$/);
159	      if (dirM) curDirection = dirM[1];
160	      const thrM = line.match(/^\s*-\s*Thread:\s*(.+?)\s*$/);
161	      if (thrM) curThread = thrM[1];
162	      const msgM = line.match(/^\s*-\s*Message:\s*(.+?)\s*$/);
163	      if (msgM) {
164	        curMessage = msgM[1];
165	        existingMessageIds.add(curMessage);
166	      }
167	    }
168	    flushLegacy();
169	  }
170	
171	  return {
172	    filePath: contactPath,
173	    category: categoryFor(contactPath),
174	    firstName,
175	    needsName: !firstName && !lastName,
176	    emails,
177	    lastSearched,
178	    existingMessageIds,
179	    existingLegacyKeys,
180	  };
181	}
182	
183	// ─── Header helpers ──────────────────────────────────────────────────────────
184	
185	function decodeRFC2047(s: string): string {
186	  return s.replace(
187	    /=\?([^?]+)\?([BbQq])\?([^?]*)\?=/g,
188	    (_m, charset, enc, encoded) => {
189	      try {
190	        if (enc.toUpperCase() === "B") {
191	          return Buffer.from(encoded, "base64").toString(
192	            charset.toLowerCase() === "utf-8" ? "utf-8" : "latin1"
193	          );
194	        }
195	        return encoded
196	          .replace(/_/g, " ")
197	          .replace(/=([0-9A-Fa-f]{2})/g, (_x: string, h: string) =>
198	            String.fromCharCode(parseInt(h, 16))
199	          );
200	      } catch {
201	        return encoded;
202	      }
203	    }
204	  );
205	}
206	
207	// Extract lowercased email addresses from a header value.
208	function addressesIn(headerValue: string): string[] {
209	  const out: string[] = [];
210	  const re = /[\w.+\-]+@[\w.\-]+\.\w+/g;
211	  let m: RegExpExecArray | null;
212	  while ((m = re.exec(headerValue)) !== null) out.push(m[0].toLowerCase());
213	  return out;
214	}
215	
216	function headerValue(
217	  headers: gmail_v1.Schema$MessagePartHeader[] | undefined,
218	  name: string
219	): string {
220	  const h = headers?.find((x) => (x.name ?? "").toLowerCase() === name);
221	  return h?.value ?? "";
222	}
223	
224	// Split a header's address list on commas that aren't inside a quoted display
225	// name (e.g. `"Harris, Josh" <josh@x.com>, else@y.com`).
226	export function splitAddressList(headerValue: string): string[] {
227	  const parts: string[] = [];
228	  let quoted = false;
229	  let cur = "";
230	  for (const ch of headerValue) {
231	    if (ch === '"') quoted = !quoted;
232	    if (ch === "," && !quoted) {
233	      parts.push(cur);
234	      cur = "";
235	    } else {
236	      cur += ch;
237	    }
238	  }
239	  if (cur.trim()) parts.push(cur);
240	  return parts;
241	}
242	
243	// Pull the display name paired with a specific address out of a From/To/Cc
244	// header, e.g. `"Josh Harris" <josh@x.com>` → "Josh Harris".
245	export function displayNameFor(headerVal: string, wantedEmails: Set<string>): string | null {
246	  for (const part of splitAddressList(decodeRFC2047(headerVal))) {
247	    const m = part.match(/^\s*"?([^"<]*?)"?\s*<\s*([^>]+?)\s*>\s*$/);
248	    if (!m) continue;
249	    const name = m[1].trim();
250	    const email = m[2].trim().toLowerCase();
251	    if (name && wantedEmails.has(email)) return name;
252	  }
253	  return null;
254	}
255	
256	// Look across From/To/Cc for a display name belonging to one of the contact's
257	// addresses — used to backfill a name for contacts recorded with only an email.
258	export function findDisplayName(
259	  headers: gmail_v1.Schema$MessagePartHeader[] | undefined,
260	  contactEmails: Set<string>
261	): string | null {
262	  for (const field of ["from", "to", "cc"]) {
263	    const name = displayNameFor(headerValue(headers, field), contactEmails);
264	    if (name) return name;
265	  }
266	  return null;
267	}
268	
269	// ─── Direction ───────────────────────────────────────────────────────────────
270	
271	// Mark sent it (Gmail SENT label, authoritative across all of Mark's historical
272	// addresses) → "To {cat}". Else contact is the sender → "From {cat}". Else Mark
273	// is only a recipient on a thread neither he nor the contact started → "CC'd".
274	function deriveDirection(
275	  labelIds: string[],
276	  fromAddrs: string[],
277	  contactEmails: Set<string>,
278	  category: string
279	): string {
280	  if (labelIds.includes("SENT")) return `To ${category}`;
281	  if (fromAddrs.some((a) => contactEmails.has(a))) return `From ${category}`;
282	  return "CC'd";
283	}
284	
285	// ─── Proposed entry ──────────────────────────────────────────────────────────
286	
287	interface ProposedEntry {
288	  ts: number; // internalDate ms, for exact ordering within a day
289	  dateStr: string;
290	  subject: string;
291	  direction: string;
292	  threadId: string;
293	  messageId: string;
294	  link: string;
295	  summary?: string; // filled by --summarize
296	}
297	
298	function legacyKey(e: ProposedEntry): string {
299	  return `${e.dateStr}|${e.subject}|${e.direction}|${e.threadId}`;
300	}
301	
302	// ─── Gmail search ────────────────────────────────────────────────────────────
303	
304	// The lower bound for a contact's search: last_searched if we have one,
305	// otherwise the per-category first-run floor (today − N years). Returns
306	// YYYY-MM-DD.
307	function effectiveAfter(contact: Contact, today: string): string {
308	  if (contact.lastSearched) return contact.lastSearched;
309	  const years = YEARS_BACK[contact.category] ?? 3;
310	  const d = new Date(today);
311	  d.setFullYear(d.getFullYear() - years);
312	  return d.toISOString().slice(0, 10);
313	}
314	
315	function buildQuery(contact: Contact, today: string): string {
316	  const addrs = contact.emails.join(" OR ");
317	  const clauses = `(from:(${addrs}) OR to:(${addrs}) OR cc:(${addrs}))`;
318	  const after = effectiveAfter(contact, today).replace(/-/g, "/"); // YYYY/MM/DD
319	  return `after:${after} ${clauses}`;
320	}
321	
322	async function searchContact(
323	  gmail: gmail_v1.Gmail,
324	  contact: Contact,
325	  today: string,
326	  wantName: boolean
327	): Promise<{ entries: ProposedEntry[]; capped: boolean; discoveredName: string | null }> {
328	  const q = buildQuery(contact, today);
329	  const ids: { id: string; threadId: string }[] = [];
330	  let pageToken: string | undefined;
331	  let capped = false;
332	
333	  do {
334	    const res = await withBackoff(
335	      () =>
336	        gmail.users.messages.list({
337	          userId: "me",
338	          q,
339	          maxResults: 500,
340	          pageToken,
341	        }),
342	      "messages.list"
343	    );
344	    for (const m of res.data.messages ?? []) {
345	      if (m.id && m.threadId) ids.push({ id: m.id, threadId: m.threadId });
346	    }
347	    pageToken = res.data.nextPageToken ?? undefined;
348	    if (ids.length >= MAX_MESSAGES_PER_CONTACT) {
349	      capped = true;
350	      break;
351	    }
352	  } while (pageToken);
353	
354	  const contactEmails = new Set(contact.emails);
355	  const entries: ProposedEntry[] = [];
356	  let discoveredName: string | null = null;
357	
358	  for (const { id } of ids) {
359	    const msg = await withBackoff(
360	      () =>
361	        gmail.users.messages.get({
362	          userId: "me",
363	          id,
364	          format: "metadata",
365	          metadataHeaders: ["From", "To", "Cc", "Subject", "Date"],
366	        }),
367	      `messages.get ${id}`
368	    );
369	    const labelIds = msg.data.labelIds ?? [];
370	    // Skip drafts — not a sent or received email.
371	    if (labelIds.includes("DRAFT")) continue;
372	
373	    const headers = msg.data.payload?.headers;
374	    if (wantName && !discoveredName) {
375	      discoveredName = findDisplayName(headers, contactEmails);
376	    }
377	    const fromAddrs = addressesIn(headerValue(headers, "from"));
378	    const subject =
379	      decodeRFC2047(headerValue(headers, "subject")).trim() || "(no subject)";
380	    const ts = Number(msg.data.internalDate ?? 0);
381	    const dateStr = new Date(ts).toISOString().slice(0, 10);
382	    const threadId = msg.data.threadId ?? "";
383	    const messageId = msg.data.id ?? "";
384	    const direction = deriveDirection(
385	      labelIds,
386	      fromAddrs,
387	      contactEmails,
388	      contact.category
389	    );
390	
391	    entries.push({
392	      ts,
393	      dateStr,
394	      subject,
395	      direction,
396	      threadId,
397	      messageId,
398	      link: `https://mail.google.com/mail/u/0/#all/${messageId}?authuser=mark@felicisholdings.com`,
399	    });
400	  }
401	
402	  // Newest first, by exact timestamp.
403	  entries.sort((a, b) => b.ts - a.ts);
404	  return { entries, capped, discoveredName };
405	}
406	
407	// ─── Dry-run report ──────────────────────────────────────────────────────────
408	
409	function renderEntry(e: ProposedEntry): string {
410	  const lines = [`- **Subject:** ${e.subject}`, `  - Direction: ${e.direction}`];
411	  if (e.summary) lines.push(`  - Summary: ${e.summary}`);
412	  lines.push(`  - Thread: ${e.threadId}`);
413	  lines.push(`  - Message: ${e.messageId}`);
414	  lines.push(`  - Link: ${e.link}`);
415	  return lines.join("\n");
416	}
417	
418	// Every contact file across all categories, alphabetical (stable resume order).
419	function discoverAllContacts(): string[] {
420	  const files: string[] = [];
421	  for (const dir of ["client", "colleagues", "friends"]) {
422	    const abs = path.join(ROOT, dir);
423	    if (!fs.existsSync(abs)) continue;
424	    for (const f of fs.readdirSync(abs)) {
425	      if (f.endsWith(".md")) files.push(`${dir}/${f}`);
426	    }
427	  }
428	  return files.sort();
429	}
430	
431	async function main() {
432	  const rawArgs = process.argv.slice(2);
433	  if (rawArgs.includes("--help")) {
434	    console.error(
435	      "Usage: npm run gmail-sync -- [contact.md ...]\n" +
436	        "With no file args, scans ALL contacts in client/, colleagues/, friends/.\n" +
437	        "By default: searches Gmail, generates summaries, and WRITES the files (advances last_searched).\n" +
438	        "  --dry-run       read-only preview — write nothing\n" +
439	        "  --no-summarize  skip the local-model Summary line"
440	    );
441	    process.exit(0);
442	  }
443	  // Default behavior: summarize + write. Opt out per run.
444	  const writeFlag = !rawArgs.includes("--dry-run");
445	  const summarizeFlag = !rawArgs.includes("--no-summarize");
446	  const fileArgs = rawArgs.filter((a) => !a.startsWith("--"));
447	  const contactFiles = fileArgs.length > 0 ? fileArgs : discoverAllContacts();
448	  if (contactFiles.length === 0) {
449	    console.error("No contact files found.");
450	    process.exit(1);
451	  }
452	  if (fileArgs.length === 0) {
453	    console.error(`No files given — scanning all ${contactFiles.length} contacts.`);
454	  }
455	
456	  const today = new Date().toISOString().slice(0, 10);
457	  console.error("Authorizing (read-only)...");
458	  const auth = await authorize();
459	  const gmail = google.gmail({ version: "v1", auth });
460	
461	  // End-of-run summary: most contacts have nothing new, so track just the ones
462	  // that changed (or would change, in --dry-run) plus any we couldn't write.
463	  const changed: { file: string; count: number }[] = [];
464	  const skippedMalformed: string[] = [];
465	
466	  for (const arg of contactFiles) {
467	    const contact = parseContact(arg);
468	    console.log(`\n${"═".repeat(72)}`);
469	    console.log(`Contact: ${contact.filePath}  [${contact.category}]`);
470	    console.log(`Addresses: ${contact.emails.join(", ") || "(none!)"}`);
471	    const after = effectiveAfter(contact, today);
472	    console.log(
473	      `Search bound: after ${after} ${
474	        contact.lastSearched
475	          ? "(incremental, from last_searched)"
476	          : `(first run, ${YEARS_BACK[contact.category] ?? 3}yr ${contact.category} floor)`
477	      }`
478	    );
479	
480	    if (contact.emails.length === 0) {
481	      console.log("⚠️  No addresses in frontmatter — skipping.");
482	      continue;
483	    }
484	
485	    const { entries, capped, discoveredName } = await searchContact(
486	      gmail,
487	      contact,
488	      today,
489	      contact.needsName
490	    );
491	    if (capped) {
492	      console.log(
493	        `⚠️  Hit the ${MAX_MESSAGES_PER_CONTACT}-message safety cap — results truncated.`
494	      );
495	    }
496	
497	    let nameFields: Record<string, string> | undefined;
498	    if (contact.needsName && discoveredName) {
499	      const { firstName: fn, lastName: ln } = splitName(discoveredName);
500	      nameFields = {};
501	      if (fn) nameFields.first_name = fn;
502	      if (ln) nameFields.last_name = ln;
503	      console.log(
504	        `👤 ${writeFlag ? "Setting" : "Would set"} name from Gmail: ${discoveredName} (was missing)`
505	      );
506	    }
507	
508	    // Split into genuinely-new vs already-present (dedup).
509	    const fresh: ProposedEntry[] = [];
510	    let already = 0;
511	    for (const e of entries) {
512	      if (contact.existingMessageIds.has(e.messageId)) {
513	        already++;
514	        continue;
515	      }
516	      if (contact.existingLegacyKeys.has(legacyKey(e))) {
517	        already++;
518	        continue;
519	      }
520	      fresh.push(e);
521	    }
522	
523	    console.log(
524	      `Found ${entries.length} message(s): ${fresh.length} new, ${already} already recorded.`
525	    );
526	    console.log(
527	      `${writeFlag ? "Setting" : "Would set"} last_searched: ${today} (currently ${
528	        contact.lastSearched ?? "unset"
529	      })`
530	    );
531	
532	    if (fresh.length > 0) {
533	      if (summarizeFlag) {
534	        console.error(
535	          `  Summarizing ${fresh.length} message(s) locally with Ollama (${OLLAMA_MODEL})...`
536	        );
537	        for (let i = 0; i < fresh.length; i++) {
538	          const e = fresh[i];
539	          const rawRes = await withBackoff(
540	            () =>
541	              gmail.users.messages.get({ userId: "me", id: e.messageId, format: "raw" }),
542	            `messages.get raw ${e.messageId}`
543	          );
544	          const summary = await summarize({
545	            rawBase64url: rawRes.data.raw ?? "",
546	            direction: e.direction,
547	            category: contact.category,
548	            firstName: contact.firstName,
549	            subject: e.subject,
550	          });
551	          if (summary) e.summary = summary;
552	          process.stderr.write(`\r  summarized ${i + 1}/${fresh.length}`);
553	        }
554	        process.stderr.write("\n");
555	      }
556	
557	      console.log(`\n--- ${writeFlag ? "New" : "Proposed new"} entries (newest first) ---`);
558	      let curDate = "";
559	      for (const e of fresh) {
560	        if (e.dateStr !== curDate) {
561	          curDate = e.dateStr;
562	          console.log(`\n### ${curDate}`);
563	        }
564	        console.log(renderEntry(e));
565	      }
566	    } else {
567	      console.log("→ No new entries to add.");
568	    }
569	
570	    if (writeFlag) {
571	      const abs = path.isAbsolute(arg) ? arg : path.join(ROOT, arg);
572	      const original = fs.readFileSync(abs, "utf-8");
573	      // Pass ALL fetched entries — mergeContact dedups against the file itself.
574	      const result = mergeContact(original, entries, today, nameFields);
575	      if (result.status === "skipped-malformed") {
576	        console.log(
577	          `\n⚠️  SKIPPED (no clean "## Mark's Email History" heading) — fix by hand: ${arg}`
578	        );
579	        skippedMalformed.push(arg);
580	      } else if (result.content !== original) {
581	        fs.writeFileSync(abs, result.content, "utf-8");
582	        console.log(`\n✍️  Wrote ${result.added} new entr(ies) → ${arg}`);
583	        changed.push({ file: arg, count: result.added });
584	      } else {
585	        console.log(`\n= No file change → ${arg}`);
586	      }
587	    } else if (fresh.length > 0) {
588	      // --dry-run: nothing written, but record what would have changed.
589	      changed.push({ file: arg, count: fresh.length });
590	    }
591	  }
592	
593	  console.log(`\n${"═".repeat(72)}`);
594	  const verb = writeFlag ? "Updated" : "Would update";
595	  const totalNew = changed.reduce((n, c) => n + c.count, 0);
596	  console.log(
597	    `${verb} ${changed.length} of ${contactFiles.length} contact(s)` +
598	      (changed.length ? ` (${totalNew} new entr${totalNew === 1 ? "y" : "ies"}):` : ".")
599	  );
600	  for (const c of changed) {
601	    console.log(`  • ${c.file} — ${c.count} new`);
602	  }
603	  if (skippedMalformed.length) {
604	    console.log(`\n⚠️  Skipped ${skippedMalformed.length} malformed file(s) — fix by hand:`);
605	    for (const f of skippedMalformed) console.log(`  • ${f}`);
606	  }
607	  console.log(
608	    writeFlag
609	      ? "\nDone — changes written to the contact files above."
610	      : "\nDRY RUN (--dry-run) — nothing was written."
611	  );
612	}
613	
614	if (require.main === module) {
615	  main().catch((err) => {
616	    console.error("\n❌  gmail-sync failed:\n");
617	    console.error(err?.message || err);
618	    process.exit(1);
619	  });
620	}
