import { describe, it, expect } from "vitest";
import { mergeContact, type FetchedEntry } from "./merge";

// A populated client-style file: frontmatter, a Mark's Email History section
// with one existing entry, and an mbox "## Email History" section that the tool
// must never touch.
const POPULATED = `---
last_name: Blyth
first_name: Don
email: "don@example.com"
last_updated: 2026-02-18
---

## Mark's Email History

### 2025-09-09
- **Subject:** Re: Rose and Crown
  - Direction: From friend
  - Thread: aaa
  - Message: msg-existing

## Email History

### 2021-01-01
- **Subject:** old mbox thing
  - Direction: From client
  - Thread: 123
  - Message-ID: <x@y>
`;

// A legacy Cowork-populated file: the entry has Thread but NO Message id.
const LEGACY = `---
last_name: Uhl
first_name: Heather
email: "heather@example.com"
last_updated: 2026-02-14
---

## Mark's Email History

### 2024-05-29
- **Subject:** Re: Coffee
  - Direction: To client
  - Summary: Mark said hi.
  - Thread: thr-legacy

## Email History

### 2020-01-01
- **Subject:** ancient
  - Direction: From client
  - Thread: 999
  - Message-ID: <a@b>
`;

// A placeholder file — searched before, nothing found.
const PLACEHOLDER = `---
last_name: Schram
first_name: Chelynne
email: "c@forces.gc.ca"
last_updated: 2026-02-02
---

## Mark's Email History

_No direct emails found between Mark and this client in Mark's Gmail (searched Feb 2026). All correspondence was handled by Heather._

## Email History

### 2025-03-28
- **Subject:** Re: Invoice
  - Direction: From client
  - Thread: 111
  - Message-ID: <z@z>
`;

// A friends/colleagues file: Mark's Email History only, NO "## Email History".
const FRIEND_NO_MBOX = `---
last_name: DeVilla
first_name: Joey
email: "joey@example.com"
last_updated: 2026-02-15
---

## Mark's Email History

### 2025-03-10
- **Subject:** Re: Catching up
  - Direction: From friend
  - Summary: Joey suggested coffee.
  - Thread: abc
  - Message: msg-old
`;

// A contact known only by email — no first_name/last_name recorded yet.
const NO_NAME = `---
email: "sam@example.com"
last_updated: 2026-02-15
---

## Mark's Email History

### 2025-03-10
- **Subject:** Re: Catching up
  - Direction: From friend
  - Thread: abc
  - Message: msg-old
`;

function entry(over: Partial<FetchedEntry>): FetchedEntry {
  return {
    ts: Date.parse("2026-06-26T12:00:00Z"),
    dateStr: "2026-06-26",
    subject: "Lunch?",
    direction: "From friend",
    threadId: "bbb",
    messageId: "msg-new",
    link: "https://mail.example/msg-new",
    ...over,
  };
}

describe("mergeContact", () => {
  it("splices a new entry and leaves the mbox Email History section untouched", () => {
    const r = mergeContact(POPULATED, [entry({})], "2026-07-02");

    expect(r.status).toBe("written");
    expect(r.added).toBe(1);
    // new entry present
    expect(r.content).toContain("### 2026-06-26");
    expect(r.content).toContain("Message: msg-new");
    // existing Mark entry preserved
    expect(r.content).toContain("Message: msg-existing");
    // the entire mbox section, verbatim, still there
    const mbox = POPULATED.slice(POPULATED.indexOf("## Email History"));
    expect(r.content).toContain(mbox);
  });

  it("does not re-add an entry whose Message id is already present", () => {
    const dup = entry({ messageId: "msg-existing", subject: "changed subject", threadId: "aaa" });
    const r = mergeContact(POPULATED, [dup], "2026-07-02");

    expect(r.added).toBe(0);
    // msg-existing appears exactly once
    expect(r.content.split("Message: msg-existing").length - 1).toBe(1);
    // the duplicate's altered subject was not written
    expect(r.content).not.toContain("changed subject");
  });

  it("does not re-add a legacy entry (no Message id) matching date+subject+direction+thread", () => {
    const sameAsLegacy = entry({
      dateStr: "2024-05-29",
      ts: Date.parse("2024-05-29T09:00:00Z"),
      subject: "Re: Coffee",
      direction: "To client",
      threadId: "thr-legacy",
      messageId: "brand-new-id", // has an id, but matches the legacy 4-tuple
    });
    const r = mergeContact(LEGACY, [sameAsLegacy], "2026-07-02");

    expect(r.added).toBe(0);
    expect(r.content).not.toContain("brand-new-id");
  });

  it("orders entries newest-first, grouped by date with no duplicate date headers", () => {
    const fetched = [
      entry({ messageId: "m-new", dateStr: "2026-06-26", ts: Date.parse("2026-06-26T10:00:00Z"), subject: "newest" }),
      entry({ messageId: "m-old", dateStr: "2024-01-01", ts: Date.parse("2024-01-01T10:00:00Z"), subject: "oldest" }),
      entry({ messageId: "m-same", dateStr: "2025-09-09", ts: Date.parse("2025-09-09T23:00:00Z"), subject: "same day newer", direction: "To friend", threadId: "zzz" }),
    ];
    const r = mergeContact(POPULATED, fetched, "2026-07-02");

    // Look only at the Mark's Email History section, not the mbox section below.
    const markSection = r.content.slice(
      r.content.indexOf("## Mark's Email History"),
      r.content.indexOf("## Email History")
    );
    const dates = [...markSection.matchAll(/^### (\d{4}-\d{2}-\d{2})/gm)].map((m) => m[1]);
    expect(dates).toEqual(["2026-06-26", "2025-09-09", "2024-01-01"]);
    // within the shared 2025-09-09 day, the 23:00 message sorts above the existing one
    expect(r.content.indexOf("same day newer")).toBeLessThan(
      r.content.indexOf("Re: Rose and Crown")
    );
  });

  it("replaces the 'No direct emails found' placeholder when entries are added", () => {
    const r = mergeContact(
      PLACEHOLDER,
      [entry({ messageId: "m1", direction: "To client", subject: "Quote" })],
      "2026-07-02"
    );

    expect(r.added).toBe(1);
    expect(r.content).not.toContain("No direct emails found");
    expect(r.content).toContain("Message: m1");
    expect(r.content).toContain("Re: Invoice"); // mbox section preserved
  });

  it("skips a file with no '## Mark's Email History' heading and leaves it byte-for-byte", () => {
    const malformed = `---
last_name: Courchesne
first_name: Carole
email: "c@x.gc.ca"
last_updated: 2026-02-18
---


### 2020-10-08
- **Subject:** RE: Post Class
  - Direction: From client
  - Thread: 174e

## Email History

### 2020-01-01
- **Subject:** ancient
  - Direction: From client
  - Thread: 1
`;
    const r = mergeContact(malformed, [entry({ messageId: "x" })], "2026-07-02");

    expect(r.status).toBe("skipped-malformed");
    expect(r.added).toBe(0);
    expect(r.content).toBe(malformed);
  });

  it("sets last_searched and last_updated to today when entries are added, keeping other frontmatter", () => {
    const r = mergeContact(POPULATED, [entry({ messageId: "m1" })], "2026-07-02");
    const fm = r.content.slice(0, r.content.indexOf("## Mark's Email History"));

    expect(fm).toContain("last_searched: 2026-07-02");
    expect(fm).toContain("last_updated: 2026-07-02");
    expect(fm).toContain("last_name: Blyth");
    expect(fm).toContain('email: "don@example.com"');
  });

  it("advances last_searched but not last_updated, and keeps the placeholder, when nothing new is found", () => {
    const r = mergeContact(PLACEHOLDER, [], "2026-07-02");
    const fm = r.content.slice(0, r.content.indexOf("## Mark's Email History"));

    expect(r.added).toBe(0);
    expect(fm).toContain("last_searched: 2026-07-02");
    expect(fm).toContain("last_updated: 2026-02-02"); // unchanged
    expect(r.content).toContain("No direct emails found"); // placeholder preserved
    expect(r.content).toContain("Re: Invoice"); // mbox preserved
  });

  it("handles a file with NO '## Email History' section (friends/colleagues) without breaking", () => {
    const r = mergeContact(
      FRIEND_NO_MBOX,
      [
        entry({
          messageId: "msg-new2",
          direction: "To friend",
          subject: "Sure, coffee works",
          dateStr: "2026-06-01",
          ts: Date.parse("2026-06-01T00:00:00Z"),
        }),
      ],
      "2026-07-02"
    );

    expect(r.status).toBe("written");
    expect(r.added).toBe(1);
    expect(r.content).toContain("Message: msg-new2"); // new entry spliced in
    expect(r.content).toContain("Message: msg-old"); // existing preserved
    expect(r.content).toContain("last_searched: 2026-07-02");
    expect(r.content).not.toContain("## Email History"); // none invented
    // ends with a single trailing newline, not a spurious blank line
    expect(r.content.endsWith("Message: msg-old\n")).toBe(true);
    expect(r.content.endsWith("\n\n")).toBe(false);
  });

  it("backfills first_name/last_name via extraFrontmatter and bumps last_updated", () => {
    const r = mergeContact(NO_NAME, [], "2026-07-02", {
      first_name: "Sam",
      last_name: "Rivera",
    });
    const fm = r.content.slice(0, r.content.indexOf("## Mark's Email History"));

    expect(fm).toContain("first_name: Sam");
    expect(fm).toContain("last_name: Rivera");
    expect(fm).toContain("last_updated: 2026-07-02"); // bumped even with 0 new entries
    expect(r.content).toContain("Message: msg-old"); // existing entry untouched
  });
});

