import * as fs from "node:fs";
import * as path from "node:path";

// Per-contact Gmail search cursor, kept OUT of the version-controlled contact
// files. Maps a repo-relative contact path to the YYYY-MM-DD it was last
// searched. This is sync bookkeeping, not contact data: it advances on every
// run, so storing it in a contact's frontmatter would rewrite every file each
// sync and bury real changes in git noise. It lives here (gitignored) instead,
// so a no-op sync leaves the contact files byte-for-byte unchanged.

const ROOT = path.resolve(__dirname, "..");
export const STATE_PATH = path.join(ROOT, ".gmail-sync-state.json");

export type SyncState = Record<string, string>;

// Normalize any contact path (relative or absolute) to a stable repo-relative
// key with forward slashes, so the same file always maps to the same entry.
export function stateKey(contactPath: string): string {
  const abs = path.isAbsolute(contactPath)
    ? contactPath
    : path.join(ROOT, contactPath);
  return path.relative(ROOT, abs).split(path.sep).join("/");
}

export function loadState(): SyncState {
  try {
    const parsed = JSON.parse(fs.readFileSync(STATE_PATH, "utf-8"));
    return parsed && typeof parsed === "object" ? (parsed as SyncState) : {};
  } catch {
