import * as fs from "node:fs";
import * as path from "node:path";
import { loadState, setLastSearched, saveState, STATE_PATH } from "./sync-state";

// ─── One-time migration ──────────────────────────────────────────────────────
//
// last_searched used to live in each contact's YAML frontmatter, so it advanced
// on every gmail-sync run and rewrote all ~340 files each time — pure git noise.
// It now lives in .gmail-sync-state.json (see sync-state.ts). This script moves
// the existing cursors there and strips the dead frontmatter line.
//
//   npx tsx src/migrate-last-searched.ts            # apply
//   npx tsx src/migrate-last-searched.ts --dry-run  # preview
//
// Idempotent: files without a last_searched line are left untouched, and an
// existing state entry is never overwritten.

const ROOT = path.resolve(__dirname, "..");
const DIRS = ["client", "colleagues", "friends"];

// Match a last_searched line only inside the leading `---` frontmatter block.
const FM_RE = /^(---\r?\n[\s\S]*?\r?\n)---/;
const LS_LINE_RE = /^last_searched:[ \t]*(.+?)[ \t]*\r?\n/m;

function discover(): string[] {
  const files: string[] = [];
  for (const dir of DIRS) {
    const abs = path.join(ROOT, dir);
    if (!fs.existsSync(abs)) continue;
    for (const f of fs.readdirSync(abs)) {
      if (f.endsWith(".md")) files.push(`${dir}/${f}`);
    }
  }
  return files.sort();
}

function main() {
  const dryRun = process.argv.includes("--dry-run");
  const state = loadState();
  let seeded = 0;
  let stripped = 0;

  for (const rel of discover()) {
    const abs = path.join(ROOT, rel);
    const raw = fs.readFileSync(abs, "utf-8");
    const fm = raw.match(FM_RE);
    if (!fm) continue;

    const lsInFm = fm[1].match(LS_LINE_RE);
    if (!lsInFm) continue; // no cursor to migrate

    const date = lsInFm[1].replace(/^["']|["']$/g, "").trim();
    // Don't clobber a cursor already recorded in state (keep the newer source of
    // truth); do seed one that's missing.
    if (state[rel] === undefined && date) {
      setLastSearched(state, rel, date);
      seeded++;
    }

    // Strip the line from the frontmatter only.
    const newFm = fm[1].replace(LS_LINE_RE, "");
    const next = raw.slice(0, fm.index!) + newFm + raw.slice(fm.index! + fm[1].length);
    if (next !== raw) {
      stripped++;
      if (!dryRun) fs.writeFileSync(abs, next, "utf-8");
    }
  }

  if (!dryRun) saveState(state);

  console.log(
    `${dryRun ? "[dry-run] " : ""}Migration: seeded ${seeded} cursor(s) into ` +
