import { describe, it, expect } from "vitest";
import * as path from "node:path";
import { stateKey, getLastSearched, setLastSearched } from "./sync-state";

const ROOT = path.resolve(__dirname, "..");

describe("stateKey", () => {
  it("normalizes a relative contact path to a forward-slash repo-relative key", () => {
    expect(stateKey("client/gary-candace.md")).toBe("client/gary-candace.md");
  });

  it("maps an absolute path under the repo to the same key as its relative form", () => {
    const abs = path.join(ROOT, "friends", "blyth-don.md");
    expect(stateKey(abs)).toBe("friends/blyth-don.md");
  });
});

describe("get/setLastSearched", () => {
  it("round-trips a cursor by contact path", () => {
    const state = {};
    expect(getLastSearched(state, "client/x.md")).toBeNull();
    setLastSearched(state, "client/x.md", "2026-07-14");
    expect(getLastSearched(state, "client/x.md")).toBe("2026-07-14");
  });

  it("keys relative and absolute forms of the same file identically", () => {
    const state = {};
    setLastSearched(state, "client/x.md", "2026-07-14");
    const abs = path.join(ROOT, "client", "x.md");
    expect(getLastSearched(state, abs)).toBe("2026-07-14");
  });
});

