if (!headingMatch || headingMatch.index === undefined) {
  // A file that is nothing but YAML frontmatter — no body after the closing
  // `---` — is just missing its section heading, not malformed. Synthesize the
  // heading so gmail-sync can populate it instead of skipping it forever. A
  // file that has real content but no heading is genuinely malformed: leave it
  // untouched for a human to fix.
  const fm = existingContent.match(/^---\r?\n[\s\S]*?\r?\n---[ \t]*(?:\r?\n)?/);
  if (fm && existingContent.slice(fm[0].length).trim() === "") {
    existingContent =
      existingContent.replace(/\s*$/, "") + "\n\n## Mark's Email History\n";
    headingMatch = existingContent.match(MARK_HEADING_RE);
  }
  if (!headingMatch || headingMatch.index === undefined) {
    return { content: existingContent, added: 0, status: "skipped-malformed" };
  }
}

