    (f) => !existingIds.has(f.messageId) && !legacyKeys.has(legacyKey(f))
  );
  const merged: Entry[] = [...existing, ...fresh];
  const added = fresh.length;

  // last_updated bumps only when we actually changed entries or discovered new
  // frontmatter (e.g. a name pulled from Gmail). The per-contact search cursor
  // (last_searched) lives in .gmail-sync-state.json, NOT here, so a no-op sync
  // leaves the file byte-for-byte unchanged and produces no git noise.
  const fields: Record<string, string> = { ...extraFrontmatter };
  if (added > 0 || (extraFrontmatter && Object.keys(extraFrontmatter).length > 0)) {
    fields.last_updated = today;
  }
  // Skip the frontmatter rewrite entirely when there is nothing to change, so a
  // no-op merge returns the head untouched (byte-for-byte, CRLF and all).
  const head =
    Object.keys(fields).length > 0 ? updateFrontmatter(rawHead, fields) : rawHead;

  // Nothing new: keep the section (entries or placeholder) byte-for-byte — with
  // no frontmatter change either, the whole file is returned untouched.
  // Otherwise regenerate the section from the merged entries.
  const heading = headingMatch[0];
  const body = added > 0 ? `\n\n${renderSection(merged)}\n` : markBody;
  let content = `${head}${heading}${body}${tail}`;
  // When Mark's section is the last thing in the file (friends/colleagues have no
  // "## Email History"), collapse the trailing blank line to a single newline.
  if (tail === "") content = content.replace(/\n+$/, "\n");

  return { content, added, status: "written" };
}

